function buildSetCookie(name, value, opts) {
  let c = name + '=' + value + '; Path=' + (opts.path || '/');
  if (opts.httpOnly) c += '; HttpOnly';
  if (opts.secure) c += '; Secure';
  if (opts.sameSite) c += '; SameSite=' + opts.sameSite;
  return c;
}

