function verifyClaims(payload, opts) {
  if (opts.now >= payload.exp) return { valid: false, reason: 'expired' };
  if (payload.iss !== opts.issuer) return { valid: false, reason: 'wrong issuer' };
  if (payload.aud !== opts.audience) return { valid: false, reason: 'wrong audience' };
  return { valid: true };
}

coding.referenceSolution:
function verifyClaims(payload, opts) {
  const { now, issuer, audience, leeway = 0 } = opts;
  if (now >= payload.exp + leeway) return { valid: false, reason: 'expired' };
  if (payload.nbf !== undefined && now + leeway < payload.nbf) return { valid: false, reason: 'not yet valid' };
  if (payload.iss !== issuer) return { valid: false, reason: 'wrong issuer' };
  const aud = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
  if (!aud.includes(audience)) return { valid: false, reason: 'wrong audience' };
  return { valid: true };
}

