class SessionStore {
  constructor(ttl) { this.ttl = ttl; this.sessions = new Map(); }
  create(id, t) { this.sessions.set(id, t + this.ttl); }
  get(id, t) {
    const expiresAt = this.sessions.get(id);
    if (expiresAt === undefined) return false;
    if (t >= expiresAt) {
      this.sessions.delete(id);
      return false;
    }
    this.sessions.set(id, t + this.ttl);
    return true;
  }
  destroy(id) { this.sessions.delete(id); }
}

