function loginLockout(attempts, maxFailures, lockMs) {
  let failures = 0;
  return attempts.map(({ t, ok }) => {
    if (failures >= maxFailures) return 'locked';
    if (ok) return 'ok';
    failures++;
    return 'fail';
  });
}

coding.referenceSolution:
function loginLockout(attempts, maxFailures, lockMs) {
  let failures = 0;
  let lockedUntil = -1;
  return attempts.map(({ t, ok }) => {
    if (t < lockedUntil) return 'locked';
    if (ok) {
      failures = 0;
      return 'ok';
    }
    failures++;
    if (failures >= maxFailures) {
      lockedUntil = t + lockMs;
      failures = 0;
    }
    return 'fail';
  });
}

