  const issues = [];
  for (const c of setCookies) {
    const name = c.split('=')[0];
    if (!c.includes('HttpOnly')) issues.push(name + ': missing HttpOnly');
    if (!c.includes('Secure')) issues.push(name + ': missing Secure');
