coding.referenceSolution:
function auditCookies(setCookies) {
  const issues = [];
  for (const c of setCookies) {
    const [first, ...attrs] = c.split(';').map((p) => p.trim());
    const name = first.split('=')[0];
    const names = attrs.map((a) => a.split('=')[0].trim().toLowerCase());
    if (!names.includes('httponly')) issues.push(name + ': missing HttpOnly');
    if (!names.includes('secure')) issues.push(name + ': missing Secure');
    if (!names.includes('samesite')) issues.push(name + ': missing SameSite');
  }
  return issues;
}

