function runSession(idle, absolute, events) {
  let session = null;
  const out = [];
  for (const [type, t] of events) {
    if (type === 'login') {
      session = { lastSeen: t };
      continue;
    }
    if (!session) out.push('no-session');
    else if (t - session.lastSeen >= idle) out.push('idle-timeout');
    else {
      session.lastSeen = t;
      out.push('ok');
    }
  }
  return out;
}

coding.referenceSolution:
function runSession(idle, absolute, events) {
  let session = null;
  const out = [];
  for (const [type, t] of events) {
    if (type === 'login') {
      session = { lastSeen: t, createdAt: t };
      continue;
    }
    if (!session) out.push('no-session');
    else if (t - session.createdAt >= absolute) {
      session = null;
      out.push('absolute-timeout');
    } else if (t - session.lastSeen >= idle) {
      session = null;
      out.push('idle-timeout');
    } else {
      session.lastSeen = t;
      out.push('ok');
    }
  }
  return out;
}

