function verifyKids(cached, remote, events, cooldown) {
  let keys = cached;
  let fetches = 0;
  let lastFetch = null;
  const results = events.map(([kid, t]) => {
    if (!keys.includes(kid) && (lastFetch === null || t - lastFetch >= cooldown)) {
      keys = remote;
      fetches++;
      lastFetch = t;
    }
    return keys.includes(kid) ? 'ok' : 'unknown-kid';
  });
  return { results, fetches };
}

