coding.referenceSolution:
function safeRedirect(next, allowedHosts) {
  if (typeof next !== 'string' || !next) return '/';
  if (next.startsWith('/')) {
    return next.startsWith('//') || next.startsWith('/\\') ? '/' : next;
  }
  const m = next.match(/^https:\/\/([^/?#]+)([/?#].*)?$/i);
  if (!m) return '/';
  const host = m[1].toLowerCase();
  if (host.includes('@') || !allowedHosts.includes(host)) return '/';
  return next;
}
